&reftitle.description;
boolftp_get FTP\Connectionftp stringlocal_filename stringremote_filename intmodeFTP_BINARY intoffset0
ftp_get recupera un file remoto dal server FTP, e lo salva in un file locale.

&reftitle.changelog;





    &Version;
    &Description;



   &ftp.changelog.ftp-param;
   &ext.ftp.changelog.mode-valueerror;


    7.3.0

     Il parametro mode ora è opzionale. In precedenza
     era obbligatorio.

  &reftitle.examples;



    Esempio di ftp_get


<?php

// definisce alcune variabili
$local_file = 'local.zip';
$server_file = 'server.zip';

// stabilisce la connessione
$ftp = ftp_connect($ftp_server);

// si collega con nome utente e password
$login_result = ftp_login($ftp, $ftp_user_name, $ftp_user_pass);

// prova a scaricare $server_file e a salvarlo in $local_file
if (ftp_get($ftp, $local_file, $server_file, FTP_BINARY)) {
    echo "Scritto correttamente in $local_file\n";
} else {
    echo "Si è verificato un problema\n";
}

// chiude la connessione
ftp_close($ftp);

?>
